#include <fastdds/rtps/RTPSDomain.h>
#include <fastdds/rtps/attributes/RTPSParticipantAttributes.h>
#include <fastdds/rtps/participant/RTPSParticipant.h>
#include <fastdds/rtps/transport/UDPv4TransportDescriptor.h>
#include <fastdds/rtps/transport/shared_mem/SharedMemTransportDescriptor.h>
#include <cstdlib>
#include <iostream>

int main(int argc, char** argv) {
    using namespace eprosima::fastrtps::rtps;
    RTPSParticipantAttributes attributes;
    auto* participant = RTPSDomain::createParticipant(std::stoi(argv[1]), attributes);
    if (!participant) return 1;
    int udp = 0, shm = 0, other = 0;
    for (auto transport : participant->getRTPSParticipantAttributes().userTransports) {
        if (dynamic_cast<eprosima::fastdds::rtps::UDPv4TransportDescriptor*>(transport.get())) ++udp;
        else if (dynamic_cast<eprosima::fastdds::rtps::SharedMemTransportDescriptor*>(transport.get())) ++shm;
        else ++other;
    }
    std::cout << "{\"udp_v4\":" << udp << ",\"shared_memory\":" << shm
              << ",\"other\":" << other << "}" << std::endl;
    return RTPSDomain::removeRTPSParticipant(participant) ? 0 : 2;
}

